                    min_r = i
                if i > max_r:
                    max_r = i
                if j < min_c:
                    min_c = j
                if j > max_c:
                    max_c = j

    # interior region (strictly inside the 5‑border)
    interior_rows = range(min_r + 1, max_r)
    interior_cols = range(min_c + 1, max_c)

    # find connected components of non‑5 cells inside the interior
    visited = [[False] * m for _ in range(n)]
    components = []

    for r in interior_rows:
        for c in interior_cols:
            if not visited[r][c] and grid[r][c] != 5:
                cells = []
                q = deque()
                q.append((r, c))
                visited[r][c] = True
                while q:
                    cr, cc = q.popleft()
                    cells.append((cr, cc))
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
