                    'cells': cells,
                    'min_r': min_rc,
                    'max_r': max_rc,
                    'min_c': min_cc,
                    'max_c': max_cc
                })

    # decide whether the walls are vertical or horizontal
    # try vertical separation first
    comps_by_c = sorted(components, key=lambda x: x['min_c'])
    vertical = True
    for i in range(len(comps_by_c) - 1):
        if comps_by_c[i]['max_c'] >= comps_by_c[i + 1]['min_c']:
            vertical = False
            break

    if not vertical:
        # try horizontal separation
        comps_by_r = sorted(components, key=lambda x: x['min_r'])
        horizontal = True
        for i in range(len(comps_by_r) - 1):
            if comps_by_r[i]['max_r'] >= comps_by_r[i + 1]['min_r']:
                horizontal = False
                break
        if horizontal:
            orientation = 'horizontal'
            sorted_comps = comps_by_r
        else:
            # default to vertical if neither works
            orientation = 'vertical'
            sorted_comps = comps_by_c
    else:
        orientation = 'vertical'
        sorted_comps = comps_by_c

    # choose the replacement values according to the orientation
    k = len(sorted_comps)
    if orientation == 'vertical':
        if k == 3:
            values = [4, 3, 2]
        elif k == 2:
            values = [4, 3]
        else:
            values = [4, 3, 2][:k]
    else:  # horizontal
        if k == 3:
            values = [2, 4, 3]
        elif k == 2:
            values = [2, 4]
